"""H707: seed repeatability and lexical/context controls for real-data rotations."""
import torch,json,time,hashlib,itertools
from pathlib import Path
from scipy.optimize import linear_sum_assignment
from transformers import AutoTokenizer
from audit_bilin18_mlp_discriminators import TOKENIZER
from run_bilin18_diverse_causal_tasks import ROOT,ART
STEM='bilin18_rotation_stability_context'
@torch.no_grad()
def main():
 torch.set_num_threads(6);torch.set_float32_matmul_precision('highest');start=time.time();paths={'data':ART/'bilin18_early_bsf_data_captures.pt','spectra':ART/'bilin18_early_rotation_spectra_captures.pt','rotations':ART/'bilin18_early_sparse_rotations_captures.pt','runner':Path(__file__)};hashes={k:hashlib.sha256(p.read_bytes()).hexdigest() for k,p in paths.items()};data=torch.load(paths['data'],weights_only=False);specs=torch.load(paths['spectra'],weights_only=False)['states'];rots=torch.load(paths['rotations'],weights_only=False)['rotations'];tok=AutoTokenizer.from_pretrained(str(TOKENIZER),local_files_only=True);cfg=dict(experiment='H707',hashes=hashes,design='All3seed pairs per site for learned/random rotations. Hungarian one-to-one maximum absolute normalized decoder cosine matching; report matched cosine and Top32support Jaccard, plus whitened rotation cosine. Top8learned seed7061directions selected by minimum decodercosine*Jaccard across otherseeds with>=32validationactivations. Training-only token/position support predictors evaluated onvalidation; within-token signedcontribution variance on repeatedlyactive trainingtokens.',limitations='Validation reused for selection/descriptive evaluation. Random same-span rotations control anisotropy but not all possible nulls. Stable directions not necessarily semantic or contextual manifolds. No intervention yet.')
 (ROOT/f'configs/{STEM}.json').write_text(json.dumps(cfg,indent=2));records=[];lexical=[];trids=data['token_ids'][:2048].flatten().cuda();vaids=data['token_ids'][2048:2304].flatten().cuda();tc=torch.bincount(trids,minlength=50257).float();vc=torch.bincount(vaids,minlength=50257).float()
 for site in ['value0','residual1']:
  sp=specs[site];mu=sp['mean'].cuda().float();V=sp['eigenvectors'][:,:256].cuda().float();sd=sp['eigenvalues'][:256].cuda().float().sqrt();x=data['activations'][site][2048:2304].reshape(-1,1152).cuda()-mu;wh=(x@V)/sd;cache={}
  def encode(w,Q):
   D=(V*sd)@Q;norm=D.norm(dim=0);code=(w@Q)*norm;ids=code.abs().topk(32,dim=-1).indices;mask=torch.zeros_like(code).scatter_(1,ids,1);return D/norm,code,mask
  for kind in ['random','learned']:
   for seed in [7061,7062,7063]:Q=rots[site,kind,seed].cuda();D,c,m=encode(wh,Q);cache[kind,seed]=(Q,D,c,m)
   for a,b in itertools.combinations([7061,7062,7063],2):
    qa,da,ca,ma=cache[kind,a];qb,db,cb,mb=cache[kind,b];scores=(da.T@db).abs();aa,bb=linear_sum_assignment(-scores.cpu().numpy());bb=torch.tensor(bb,device='cuda');cos=scores[torch.arange(256,device='cuda'),bb];rotcos=(qa.T@qb).abs()[torch.arange(256,device='cuda'),bb];matched=mb[:,bb];inter=(ma*matched).sum(0);union=(ma+matched-ma*matched).sum(0);jac=inter/union.clamp_min(1);rec=dict(site=site,kind=kind,seed_a=a,seed_b=b,mean_decoder_cosine=float(cos.mean()),mean_whitened_cosine=float(rotcos.mean()),mean_support_jaccard=float(jac.mean()),directions_cosine_above_09=int((cos>.9).sum()),assignments=bb.cpu().tolist(),cosines=cos.cpu().tolist(),jaccards=jac.cpu().tolist());records.append(rec);print({k:rec[k] for k in ['site','kind','seed_a','seed_b','mean_decoder_cosine','mean_whitened_cosine','mean_support_jaccard','directions_cosine_above_09']},flush=True)
  refs=[r for r in records if r['site']==site and r['kind']=='learned' and r['seed_a']==7061];scores=torch.stack([torch.tensor(r['cosines'],device='cuda')*torch.tensor(r['jaccards'],device='cuda') for r in refs]).min(0).values;Q,D,code,mask=cache['learned',7061];scores[mask.sum(0)<32]=-1;chosen=scores.topk(8).indices;assert scores[chosen].min()>=0
  train=data['activations'][site][:2048].reshape(-1,1152).cuda()-mu;_,zt,yt=encode((train@V)/sd,Q);zt,yt=zt[:,chosen],yt[:,chosen];yv=mask[:,chosen];prior=yt.mean(0);sums=torch.zeros(50257,8,device='cuda').index_add_(0,trids,yt);tokenpred=(sums+8*prior)/(tc[:,None]+8);pospred=(yt.reshape(2048,16,8).sum(0)+8*prior)/(2048+8);den=(yv-prior).square().mean(0);tokenskill=1-(tokenpred[vaids]-yv).square().mean(0)/den;positionskill=1-(pospred.repeat(256,1)-yv).square().mean(0)/den
  for i,f in enumerate(chosen.tolist()):
   active=yt[:,i]>0;ids=trids[active];c=zt[active,i];counts=torch.bincount(ids,minlength=50257).float();sums=torch.zeros(50257,device='cuda').index_add_(0,ids,c);means=sums/counts.clamp_min(1);repeat=counts[ids]>=8;subset=c[repeat];variance=float((subset-means[ids[repeat]]).square().sum()/(subset-subset.mean()).square().sum()) if len(subset)>1 else None;vsum=torch.zeros(50257,device='cuda').index_add_(0,vaids,yv[:,i]);repeated=vc>=4;mixed=int((repeated&(vsum>0)&(vsum<vc)).sum());top=torch.bincount(vaids[yv[:,i]>0],minlength=50257).topk(8);lexical.append(dict(site=site,direction=f,stability_score=float(scores[f]),validation_active=int(yv[:,i].sum()),token_brier_skill=float(tokenskill[i]),position_brier_skill=float(positionskill[i]),within_token_active_coefficient_variance_fraction=variance,eligible_repeat_examples=int(repeat.sum()),mixed_support_repeated_validation_token_types=mixed,top_active_tokens=[dict(token=tok.decode([int(t)]),count=int(n)) for n,t in zip(top.values,top.indices) if n>0]))
  del train,cache,wh,x
 audits=dict(hashes_unchanged={k:hashlib.sha256(p.read_bytes()).hexdigest()==hashes[k] for k,p in paths.items()},finite=all(torch.isfinite(torch.tensor(r['mean_decoder_cosine'])).item() for r in records),test_evaluations=0,whole_model_forwards=0);assert all(audits['hashes_unchanged'].values()) and audits['finite'];(ART/f'{STEM}.json').write_text(json.dumps(dict(status='complete',config=cfg,records=records,lexical=lexical,audits=audits,elapsed_seconds=time.time()-start),indent=2));print(audits,flush=True)
if __name__=='__main__':main()
